def isValidBST(root):
    def valid(node, lo, hi):
        if not node: return True
        if not (lo < node.val < hi): return False  # 越界非法
        left_ok = valid(node.left, lo, node.val)  # 左树上界收紧
        return left_ok and valid(node.right, node.val, hi)
    return valid(root, float('-inf'), float('inf'))

def preorderTraversal(root):
    res, stack = [], [root] if root else []
    while stack:
        node = stack.pop()        # 弹出当前子树根
        res.append(node.val)      # 先访问根
        if node.right:
            stack.append(node.right)  # 右先入后出
        if node.left:
            stack.append(node.left)
    return res

from collections import deque
def rightSideView(root):
    if not root: return []
    res, q = [], deque([root])
    while q:
        size = len(q)
        for i in range(size):
            node = q.popleft()
            if i == size - 1:     # 本层最后弹出的
                res.append(node.val)
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
    return res
